-- Seed aesthetic_library with 17 initial entries from aesthetic-library.json
INSERT OR IGNORE INTO aesthetic_library (id, category, subcategory, name_i18n, description_i18n, emotion_tags, composed_of, prompt_fragment_zh, prompt_fragment_en, negative_fragment, adjustable_params, thumbnail_r2_key, source, status, contributor_id, usage_count, remix_count, rating_avg, mode_scope) VALUES
('light-source-natural-goldenhour','light','source','{"zh-HK":"自然光 · 黃金時刻","en":"Natural Light · Golden Hour","zh-CN":"自然光 · 黄金时刻"}','{"zh-HK":"以日出後或日落前的柔和暖光拍攝，光線角度低、色溫暖，最能營造懷舊與親切的氛圍，特別適合記錄長者的人生故事。","en":"Soft warm light shortly after sunrise or before sunset. The low angle and warm tone create a nostalgic, gentle mood, ideal for recording an elder''s life story.","zh-CN":"以日出后或日落前的柔和暖光拍摄，光线角度低、色温暖，最能营造怀旧与亲切的氛围，特别适合记录长者的人生故事。"}','["懷舊","親切","溫暖"]','[]','黃金時刻自然光，柔和暖色調，低角度側光','golden hour natural light, soft warm tone, low-angle side lighting','harsh shadows, overexposed highlights, cold blue cast','{"colorTemp":"warm","lightPosition":"side-low","intensity":"soft"}','aesthetic/seed/goldenhour.jpg','book','published',NULL,0,0,0,'["both"]'),
('light-position-backlight','light','position','{"zh-HK":"逆光","en":"Backlight","zh-CN":"逆光"}','{"zh-HK":"光源置於被攝主體之後，勾勒出清晰的輪廓與髮絲光，壓抑正面細節，營造神秘、夢幻而富魅力的感受。","en":"Light placed behind the subject outlines a clear silhouette and rim light, suppressing frontal detail to create a mysterious, dreamy and alluring feel.","zh-CN":"光源置于被摄主体之后，勾勒出清晰的轮廓与发丝光，压抑正面细节，营造神秘、梦幻而富魅力的感受。"}','["神秘","夢幻","詩意"]','[]','逆光，輪廓光，髮絲光，背景光暈','backlight, rim light, hair light, background glow, silhouette','flat frontal lighting, no depth','{"lightPosition":"behind","intensity":"strong"}','aesthetic/seed/backlight.jpg','book','published',NULL,0,0,0,'["both"]'),
('light-position-toplight','light','position','{"zh-HK":"頂光","en":"Top Light","zh-CN":"顶光"}','{"zh-HK":"光源自被攝主體上方向下照射，於眼窩與下巴形成陰影，帶來莊重、威嚴而肅穆的氣氛，適合企業領袖傳承的人物肖像。","en":"Light from directly above casts shadows in the eye sockets and under the chin, giving a solemn, authoritative mood suited to founder-legacy portraits.","zh-CN":"光源自被摄主体上方向下照射，于眼窝与下巴形成阴影，带来庄重、威严而肃穆的气氛，适合企业领袖传承的人物肖像。"}','["莊重","威嚴","肅穆"]','[]','頂光，向下照射，莊重威嚴，肖像布光','top lighting, light from above, solemn dignified portrait lighting','flat lighting, playful mood, casual snapshot','{"lightPosition":"top","intensity":"medium"}','aesthetic/seed/toplight.jpg','book','published',NULL,0,0,0,'["legacy"]'),
('light-color-warm','light','color','{"zh-HK":"暖光","en":"Warm Light","zh-CN":"暖光"}','{"zh-HK":"光色偏紅、偏黃，令畫面帶來親切、溫暖而柔和的氛圍，是長者向內容的首選色調，看得舒服亦有人情味。","en":"Light shifted toward red and yellow gives a warm, gentle and approachable atmosphere, the preferred tone for elder-facing content.","zh-CN":"光色偏红、偏黄，令画面带来亲切、温暖而柔和的氛围，是长者向内容的首选色调，看得舒服亦有人情味。"}','["溫暖","親切","柔和"]','[]','暖色光，偏黃偏紅，柔和溫暖氛圍','warm light, amber and red tint, soft cozy atmosphere','cold blue tone, clinical white balance','{"colorTemp":"warm"}','aesthetic/seed/warmlight.jpg','book','published',NULL,0,0,0,'["both"]'),
('material-plain-authentic','material','texture','{"zh-HK":"原始樸真","en":"Raw & Authentic","zh-CN":"原始朴真"}','{"zh-HK":"強調未經修飾的真實質感——粗糙的牆面、舊木、麻布、歲月痕跡，最能承載真人真事的重量，是傳承模式的核心質感。","en":"Emphasises unpolished, real textures — rough walls, aged wood, linen, marks of time — carrying the weight of true stories; a core texture for Legacy mode.","zh-CN":"强调未经修饰的真实质感——粗糙的墙面、旧木、麻布、岁月痕迹，最能承载真人真事的重量，是传承模式的核心质感。"}','["真實","質樸","歲月"]','[]','原始樸真質感，粗糙牆面，舊木紋理，歲月痕跡，寫實','raw authentic texture, rough wall, aged wood grain, marks of time, documentary realism','glossy plastic, over-polished, artificial sheen','{"texture":"matte-rough"}','aesthetic/seed/authentic.jpg','book','published',NULL,0,0,0,'["legacy"]'),
('material-soft-cotton','material','texture','{"zh-HK":"輕軟棉絨","en":"Soft Cotton","zh-CN":"轻软棉绒"}','{"zh-HK":"柔軟、蓬鬆、帶絨毛質感，令畫面溫柔舒適，適合溫馨家庭題材與長者觀看的療癒短劇。","en":"Soft, fluffy, fuzzy texture that makes the image tender and comforting, suited to warm family themes and soothing drama for elders.","zh-CN":"柔软、蓬松、带绒毛质感，令画面温柔舒适，适合温馨家庭题材与长者观看的疗愈短剧。"}','["溫柔","舒適","療癒"]','[]','輕軟棉絨質感，蓬鬆柔軟，溫柔舒適','soft cotton texture, fluffy, gentle and cozy','hard metallic surface, sharp edges','{"texture":"soft-fluffy"}','aesthetic/seed/cotton.jpg','book','published',NULL,0,0,0,'["drama"]'),
('artmovement-song-landscape','art_movement','chinese','{"zh-HK":"宋代山水","en":"Song Dynasty Landscape","zh-CN":"宋代山水"}','{"zh-HK":"以留白、淡墨、層疊遠山營造空靈意境，格調高雅內斂，適合戲劇模式的詩意片頭或回憶片段。","en":"Uses negative space, light ink and layered distant mountains for an ethereal, refined mood; suited to poetic openings or memory scenes in Drama mode.","zh-CN":"以留白、淡墨、层叠远山营造空灵意境，格调高雅内敛，适合戏剧模式的诗意片头或回忆片段。"}','["空靈","高雅","詩意"]','[]','宋代山水畫風，水墨留白，層疊遠山，淡雅意境','Song dynasty landscape painting, ink wash, negative space, layered distant mountains, refined mood','saturated colors, modern elements, cluttered composition','{}','aesthetic/seed/song-landscape.jpg','book','published',NULL,0,0,0,'["drama"]'),
('illustration-watercolor','illustration','painting','{"zh-HK":"水彩畫","en":"Watercolour","zh-CN":"水彩画"}','{"zh-HK":"以透明水彩的暈染、柔邊與淡雅色彩呈現，溫柔而不刺眼，適合長者向療癒短劇與家庭傳承片頭。","en":"Transparent watercolour bleeds, soft edges and gentle colours; tender and easy on the eyes, suited to soothing elder drama and family-legacy openings.","zh-CN":"以透明水彩的晕染、柔边与淡雅色彩呈现，温柔而不刺眼，适合长者向疗愈短剧与家庭传承片头。"}','["柔和","療癒","淡雅"]','[]','水彩畫風，透明暈染，柔和邊緣，淡雅色彩','watercolour illustration, transparent bleeds, soft edges, gentle pastel colours','hard vector lines, neon colors, 3D render','{}','aesthetic/seed/watercolor.jpg','book','published',NULL,0,0,0,'["both"]'),
('illustration-papercut','illustration','craft','{"zh-HK":"剪紙畫","en":"Paper-cut Art","zh-CN":"剪纸画"}','{"zh-HK":"以層疊剪紙的分明輪廓與立體陰影呈現，富民俗與節慶氣息，適合農曆新年等長者熟悉的節日題材短劇。","en":"Layered paper-cut with crisp outlines and depth shadows, rich in folk and festive feel; suited to Lunar New Year and other festivals familiar to elders.","zh-CN":"以层叠剪纸的分明轮廓与立体阴影呈现，富民俗与节庆气息，适合农历新年等长者熟悉的节日题材短剧。"}','["民俗","節慶","喜慶"]','[]','剪紙畫風，層疊紙藝，分明輪廓，立體陰影，節慶民俗','paper-cut art style, layered paper craft, crisp outlines, depth shadows, festive folk motif','photorealistic, gradient shading','{}','aesthetic/seed/papercut.jpg','book','published',NULL,0,0,0,'["drama"]'),
('lens-portrait-105mm','lens','portrait','{"zh-HK":"人像淺景深 · 105mm f/1.8","en":"Portrait Shallow DoF · 105mm f/1.8","zh-CN":"人像浅景深 · 105mm f/1.8"}','{"zh-HK":"中長焦大光圈鏡頭，令主體清晰、背景柔化模糊，突出人物、隔絕雜亂，是人物傳記與訪談肖像的理想選擇。","en":"A medium-telephoto fast lens keeps the subject sharp while softly blurring the background, isolating the person from clutter; ideal for biography and interview portraits.","zh-CN":"中长焦大光圈镜头，令主体清晰、背景柔化模糊，突出人物、隔绝杂乱，是人物传记与访谈肖像的理想选择。"}','["聚焦","專業","肖像"]','[]','105mm f/1.8 人像鏡頭，淺景深，背景柔化模糊，主體清晰','105mm f/1.8 portrait lens, shallow depth of field, creamy background blur, sharp subject','wide angle distortion, everything in focus, busy background','{"focalLength":"105mm","aperture":"f/1.8","depthOfField":"shallow"}','aesthetic/seed/105mm.jpg','book','published',NULL,0,0,0,'["legacy"]'),
('atmosphere-hk-1980s-film','atmosphere','era','{"zh-HK":"八零年代香港 · 膠片質感","en":"1980s Hong Kong · Film Look","zh-CN":"八零年代香港 · 胶片质感"}','{"zh-HK":"以柯達膠片的顆粒、暖偏色與柔和曝光，重現一九八零年代香港唐樓、街市與霓虹的年代感，是家庭傳承回憶片段的靈魂質感。修復舊照時只作去噪與破損修補，保留原有膠片顆粒與色偏，不修成現代高清。","en":"Kodak film grain, warm colour cast and soft exposure recreate 1980s Hong Kong tenements, wet markets and neon. The soul texture for family-legacy memory scenes. When restoring old photos, only denoise and repair damage while keeping the original grain and colour cast — do not modernise into HD.","zh-CN":"以柯达胶片的颗粒、暖偏色与柔和曝光，重现一九八零年代香港唐楼、街市与霓虹的年代感，是家庭传承回忆片段的灵魂质感。修复旧照时只作去噪与破损修补，保留原有胶片颗粒与色偏，不修成现代高清。"}','["懷舊","年代感","香港"]','["light-source-natural-goldenhour","material-plain-authentic","lens-portrait-105mm"]','一九八零年代香港，柯達膠片質感，膠片顆粒，暖偏色，唐樓街市霓虹，柔和曝光','1980s Hong Kong, Kodak film look, film grain, warm colour cast, tenement buildings wet market neon signs, soft exposure','modern HD, digital sharpness, oversaturated, contemporary buildings','{"era":"1980s","grain":"medium","colorTemp":"warm"}','aesthetic/seed/hk-1980s.jpg','curated','published',NULL,0,0,0,'["legacy"]'),
('atmosphere-hk-1990s-neon','atmosphere','era','{"zh-HK":"九零年代香港 · 夜市霓虹","en":"1990s Hong Kong · Neon Night","zh-CN":"九零年代香港 · 夜市霓虹"}','{"zh-HK":"以密集的霓虹招牌、濕潤街道反光與暖冷交錯的燈光，重現九零年代香港夜晚的繁華氣息，適合戲劇模式懷舊都市題材。","en":"Dense neon signs, wet reflective streets and mixed warm-cool lighting recreate the bustling 1990s Hong Kong night, suited to nostalgic urban Drama themes.","zh-CN":"以密集的霓虹招牌、湿润街道反光与暖冷交错的灯光，重现九零年代香港夜晚的繁华气息，适合戏剧模式怀旧都市题材。"}','["繁華","懷舊","都市"]','["light-color-warm","light-position-backlight"]','九零年代香港夜晚，密集霓虹招牌，濕潤街道反光，暖冷交錯燈光，都市繁華','1990s Hong Kong night, dense neon signs, wet reflective streets, mixed warm and cool lights, bustling city','daytime, rural, minimalist, empty streets','{"era":"1990s","colorTemp":"mixed"}','aesthetic/seed/hk-1990s-neon.jpg','curated','published',NULL,0,0,0,'["drama"]'),
('atmosphere-warm-family-home','atmosphere','mood','{"zh-HK":"溫馨家庭 · 窗光客廳","en":"Warm Family · Window-lit Living Room","zh-CN":"温馨家庭 · 窗光客厅"}','{"zh-HK":"以柔和的窗光灑進家居客廳，配暖色調與生活細節，營造親密、安穩的家庭氛圍，是家庭傳承與溫馨短劇的通用基調。","en":"Soft window light filling a home living room with warm tones and everyday details, creating an intimate, secure family mood; a versatile base for family legacy and warm drama.","zh-CN":"以柔和的窗光洒进家居客厅，配暖色调与生活细节，营造亲密、安稳的家庭氛围，是家庭传承与温馨短剧的通用基调。"}','["溫馨","親密","安穩"]','["light-color-warm","material-soft-cotton"]','溫馨家庭客廳，柔和窗光，暖色調，生活細節，親密安穩','cozy family living room, soft window light, warm tones, everyday details, intimate and secure','cold studio, empty space, harsh lighting','{"lightPosition":"window-side","colorTemp":"warm"}','aesthetic/seed/family-home.jpg','curated','published',NULL,0,0,0,'["both"]'),
('atmosphere-founder-portrait','atmosphere','mood','{"zh-HK":"企業領袖 · 莊重人物肖像","en":"Founder Legacy · Dignified Portrait","zh-CN":"企业领袖 · 庄重人物肖像"}','{"zh-HK":"以頂光與暖光配大光圈淺景深，突出人物的沉穩與威嚴，背景簡潔，適合企業領袖傳承的正式肖像與訪談畫面。","en":"Top light and warm light with a fast shallow-DoF lens highlight the subject''s poise and authority against a clean background; ideal for formal founder-legacy portraits and interviews.","zh-CN":"以顶光与暖光配大光圈浅景深，突出人物的沉稳与威严，背景简洁，适合企业领袖传承的正式肖像与访谈画面。"}','["莊重","威嚴","沉穩"]','["light-position-toplight","light-color-warm","lens-portrait-105mm"]','企業領袖肖像，頂光配暖光，105mm 淺景深，簡潔背景，沉穩威嚴','founder portrait, top light with warm tone, 105mm shallow depth of field, clean background, poised and authoritative','cluttered background, casual snapshot, playful mood','{"lightPosition":"top","colorTemp":"warm","depthOfField":"shallow"}','aesthetic/seed/founder-portrait.jpg','curated','published',NULL,0,0,0,'["legacy"]'),
('illustration-ink-animation','illustration','animation','{"zh-HK":"水墨動漫","en":"Ink-wash Animation","zh-CN":"水墨动漫"}','{"zh-HK":"結合傳統水墨的暈染筆觸與動畫的流動感，畫面雅緻而富東方韻味，適合戲劇模式富文化底蘊的敘事片段。","en":"Combines traditional ink-wash brushwork with animated fluidity for an elegant, distinctly Oriental look; suited to culturally rich narrative scenes in Drama mode.","zh-CN":"结合传统水墨的晕染笔触与动画的流动感，画面雅致而富东方韵味，适合戏剧模式富文化底蕴的叙事片段。"}','["雅緻","東方","文化"]','["artmovement-song-landscape"]','水墨動漫風，水墨暈染筆觸，流動感，東方韻味，雅緻','ink-wash animation style, ink bleed brushwork, fluid motion, oriental elegance','3D render, western cartoon, flat vector','{}','aesthetic/seed/ink-animation.jpg','book','published',NULL,0,0,0,'["drama"]'),
('portrait-oriental-grace','atmosphere','portrait_style','{"zh-HK":"東方韻致 · 氣質人像","en":"Oriental Grace · Character Portrait","zh-CN":"东方韵致 · 气质人像"}','{"zh-HK":"以柔和光線與典雅構圖突出人物的東方氣質與神韻，著重神情與格調而非外表誘惑，適合戲劇模式中優雅的男女角色形象。","en":"Soft light and elegant composition highlight a subject''s Oriental poise and presence, emphasising expression and refinement rather than allure; suited to graceful male or female characters in Drama mode.","zh-CN":"以柔和光线与典雅构图突出人物的东方气质与神韵，着重神情与格调而非外表诱惑，适合戏剧模式中优雅的男女角色形象。"}','["典雅","氣質","東方"]','["light-source-natural-goldenhour","lens-portrait-105mm"]','東方氣質人像，柔和光線，典雅構圖，神情細膩，格調高雅','oriental character portrait, soft lighting, elegant composition, refined expression, graceful','revealing clothing, suggestive pose, nudity','{"colorTemp":"neutral-warm","depthOfField":"shallow"}','aesthetic/seed/oriental-grace.jpg','book','published',NULL,0,0,0,'["drama"]'),
('portrait-vibrant-energy','atmosphere','portrait_style','{"zh-HK":"活力四射 · 陽光人像","en":"Vibrant Energy · Sunlit Portrait","zh-CN":"活力四射 · 阳光人像"}','{"zh-HK":"以明亮陽光與飽和暖色捕捉人物的活力與朝氣，笑容自然、動感十足，適合戲劇模式中健康正面的男女角色。","en":"Bright sunlight and saturated warm tones capture a subject''s vitality and freshness, with natural smiles and dynamic energy; suited to healthy, positive male or female characters in Drama mode.","zh-CN":"以明亮阳光与饱和暖色捕捉人物的活力与朝气，笑容自然、动感十足，适合戏剧模式中健康正面的男女角色。"}','["活力","陽光","朝氣"]','["light-source-natural-goldenhour","light-color-warm"]','活力人像，明亮陽光，飽和暖色，自然笑容，動感朝氣','vibrant portrait, bright sunshine, saturated warm colours, natural smile, dynamic energy','revealing clothing, suggestive pose, gloomy mood','{"colorTemp":"warm","intensity":"bright"}','aesthetic/seed/vibrant-energy.jpg','book','published',NULL,0,0,0,'["drama"]');
